ADVENTURES["primary2-unit-01"]=[{"name":"Listen and sequence","intro":"Tola waters a small plant. Next, she puts the watering can away. Last, she washes her hands. Explain the key concept carefully and demonstrate it on paper. Ask an adult for support when needed.","icon":"ABC","questions":[{"prompt":"What happens after watering?","choices":["Tola puts the watering can away.","She sweeps the floor first."],"answer":0,"explanation":"Tola puts the watering can away. Sequencing uses clues first, next and last. Record whether help was needed. This response follows the example you just explored.","picture":""},{"prompt":"Which response follows the reading or writing model in this lesson?","choices":["She sweeps the floor first.","Tola puts the watering can away."],"answer":1,"explanation":"Review the model and answer again using your own explanation. The lesson gives a worked example and a chance to practise.","picture":""}]},{"name":"Build describing sentences","intro":"A bright red kite flies over the field. Explain the key concept carefully and demonstrate it on paper. Ask an adult for support when needed.","icon":"ABC","questions":[{"prompt":"Which word tells the kite's colour?","choices":["Red.","Blue."],"answer":0,"explanation":"Red. A describing word gives us a detail about a noun. Record whether help was needed. This response follows the example you just explored.","picture":""},{"prompt":"Which response follows the reading or writing model in this lesson?","choices":["Blue.","Red."],"answer":1,"explanation":"Review the model and answer again using your own explanation. The lesson gives a worked example and a chance to practise.","picture":""}]},{"name":"Ask and answer questions","intro":"Zara takes her notebook to class. The story does not name its colour. Explain the key concept carefully and demonstrate it on paper. Ask an adult for support when needed.","icon":"ABC","questions":[{"prompt":"Does the story tell us the notebook's colour?","choices":["No.","Yes."],"answer":0,"explanation":"No. Good readers check what the words actually say. Record whether help was needed. This response follows the example you just explored.","picture":""},{"prompt":"Which response follows the reading or writing model in this lesson?","choices":["Yes.","No."],"answer":1,"explanation":"Review the model and answer again using your own explanation. The lesson gives a worked example and a chance to practise.","picture":""}]},{"name":"Tens and ones","intro":"Two bundles of ten sticks and four single sticks make twenty-four. Explain the key concept carefully and demonstrate it on paper. Ask an adult for support when needed.","icon":"123","questions":[{"prompt":"How many tens are in 24?","choices":["Two.","Four."],"answer":0,"explanation":"Two. The digit 2 counts groups of ten. Record whether help was needed. This response follows the example you just explored.","picture":""},{"prompt":"Which response follows the mathematics model in this lesson?","choices":["Four.","Two."],"answer":1,"explanation":"Review the model and answer again using your own explanation. The lesson gives a worked example and a chance to practise.","picture":""}]},{"name":"Add two-digit numbers","intro":"Twelve plus thirteen equals twenty-five: add ten and ten, then two and three. Explain the key concept carefully and demonstrate it on paper. Ask an adult for support when needed.","icon":"123","questions":[{"prompt":"What is 12 + 13?","choices":["25.","35."],"answer":0,"explanation":"25. Two tens and five ones make 25. Record whether help was needed. This response follows the example you just explored.","picture":""},{"prompt":"Which response follows the mathematics model in this lesson?","choices":["35.","25."],"answer":1,"explanation":"Review the model and answer again using your own explanation. The lesson gives a worked example and a chance to practise.","picture":""}]},{"name":"Compare shapes","intro":"A square has four equal straight sides; a rectangle has four straight sides and opposite sides equal. Explain the key concept carefully and demonstrate it on paper. Ask an adult for support when needed.","icon":"123","questions":[{"prompt":"Which shape has four equal sides?","choices":["Square.","Triangle."],"answer":0,"explanation":"Square. Look at the sides, not the drawing's colour. Record whether help was needed. This response follows the example you just explored.","picture":""},{"prompt":"Which response follows the mathematics model in this lesson?","choices":["Triangle.","Square."],"answer":1,"explanation":"Review the model and answer again using your own explanation. The lesson gives a worked example and a chance to practise.","picture":""}]}];
